const out = [];
const ts = (t) => { const n = Number(t); return Number.isFinite(n) && n > 0 ? new Date(n * 1000).toISOString() : ''; };
const textoDe = (m) => m.text?.body || m.button?.text || m.interactive?.button_reply?.title || m.interactive?.list_reply?.title
  || m.image?.caption || m.video?.caption || m.document?.caption || m.reaction?.emoji || '';
for (const it of $input.all()) {
  const b = it.json.body || {};
  for (const e of (b.entry || [])) {
    for (const c of (e.changes || [])) {
      const v = c.value || {};
      const md = v.metadata || {};
      const base = { waba_id: e.id != null ? String(e.id) : '', phone_number_id: md.phone_number_id || '', telefone_negocio: md.display_phone_number || '' };
      const nome = v.contacts?.[0]?.profile?.name || '';
      for (const m of (v.messages || [])) {
        out.push({ json: { ...base, contato_wa_id: m.from || '', contato_nome: nome, tipo: 'message', msg_tipo: m.type || '', mid: m.id || '', texto: textoDe(m), evento_em: ts(m.timestamp), payload: JSON.stringify({ field: c.field, message: m, contacts: v.contacts || [] }) } });
      }
      for (const m of (v.message_echoes || [])) {
        out.push({ json: { ...base, contato_wa_id: m.to || '', contato_nome: '', tipo: 'echo', msg_tipo: m.type || '', mid: m.id || '', texto: textoDe(m), evento_em: ts(m.timestamp), payload: JSON.stringify({ field: c.field, echo: m }) } });
      }
      for (const s of (v.statuses || [])) {
        out.push({ json: { ...base, contato_wa_id: s.recipient_id || '', contato_nome: '', tipo: 'status', msg_tipo: s.status || '', mid: s.id || '', texto: (s.errors || []).map((x) => x.title || x.message).join('; '), evento_em: ts(s.timestamp), payload: JSON.stringify({ field: c.field, status: s }) } });
      }
      if (!(v.messages || []).length && !(v.statuses || []).length && !(v.message_echoes || []).length) {
        out.push({ json: { ...base, contato_wa_id: '', contato_nome: '', tipo: 'outro', msg_tipo: c.field || '', mid: '', texto: '', evento_em: ts(e.time), payload: JSON.stringify(c) } });
      }
    }
  }
}
return out;
